const dishes = {
            fish: {
                name: 'Grilled Fish',
                img: 'data:image/webp;base64,',
                alt: 'Exploded photo of grilled fish, couscous, vegetables and sauce',
                allergens: ['Fish', 'Wheat / gluten (if couscous is wheat-based)', 'Milk (if the white sauce contains dairy)']
            },
            cake: {
                name: 'Cheesecake',
                img: 'data:image/webp;base64,',
                alt: 'Exploded photo of cheesecake with strawberry, ice cream, mint and sauce',
                allergens: ['Milk (likely)', 'Eggs (recipe-dependent)', 'Wheat / gluten (if biscuit or flour used)', 'Tree nuts (check garnish)']
            }
        };
        const overlay = document.getElementById('overlay'),
            img = document.getElementById('exploded'),
            chips = document.getElementById('chips'),
            close = document.getElementById('close');
        let last = null;

        function show(key, button) {
            last = button;
            const d = dishes[key];
            document.getElementById('dishTitle').textContent = d.name;
            img.src = d.img;
            img.alt = d.alt;
            chips.replaceChildren(...d.allergens.map(s => {
                const e = document.createElement('span');
                e.className = 'chip';
                e.textContent = s;
                return e
            }));
            overlay.hidden = false;
            document.body.style.overflow = 'hidden';
            replay();
            close.focus()
        }

        function hide() {
            overlay.hidden = true;
            document.body.style.overflow = '';
            last?.focus()
        }

        function replay() {
            img.style.animation = 'none';
            void img.offsetWidth;
            img.style.animation = ''
        }
        document.querySelectorAll('[data-dish]').forEach(b => b.addEventListener('click', () => show(b.dataset.dish, b)));
        close.onclick = hide;
        document.getElementById('replay').onclick = replay;
        overlay.addEventListener('click', e => {
            if (e.target === overlay) hide()
        });
        document.addEventListener('keydown', e => {
            if (!overlay.hidden && e.key === 'Escape') hide();
            if (!overlay.hidden && e.key === 'Tab') {
                const target = document.activeElement === close ? document.getElementById('replay') : close;
                e.preventDefault();
                target.focus()
            }
        });